// Regenerates GVA_template.js from "GVA Model Template.xlsx" so the app can use the template offline,
// including when GVA_Model_v4.0.html is opened straight from disk.
// Run from the repo root after editing the template:  node src/tools/embed-template.js
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const base64 = fs.readFileSync(path.join(root, 'GVA Model Template.xlsx')).toString('base64');
fs.writeFileSync(
  path.join(root, 'GVA_template.js'),
  '// Generated by src/tools/embed-template.js from "GVA Model Template.xlsx". Do not edit by hand.\n'
  + `const GVA_TEMPLATE_BASE64 = '${base64}';\n`
);
console.log(`GVA_template.js written (${base64.length} characters)`);
